class RiskManagement:
    """Main risk management interface"""

    def __init__(self, parameters: RiskParameters=DEFAULT_RISK_PARAMS):
        self.parameters = parameters
        self.governance = RiskGovernance()
        self.risk_budgeting = None

    def comprehensive_risk_analysis(self, returns_data: Union[np.ndarray, Dict[str, np.ndarray]], weights: Optional[np.ndarray]=None, portfolio_value: float=1000000) -> Dict:
        """Perform comprehensive risk analysis"""
        if isinstance(returns_data, dict):
            returns_matrix = np.array([returns_data[asset] for asset in returns_data.keys()]).T
            if weights is None:
                weights = np.ones(len(returns_data)) / len(returns_data)
            portfolio_returns = np.dot(returns_matrix, weights)
            asset_names = list(returns_data.keys())
        else:
            portfolio_returns = np.array(returns_data)
            returns_matrix = portfolio_returns.reshape(-1, 1)
            weights = np.array([1.0])
            asset_names = ['Portfolio']
        results = {'basic_risk_metrics': self._calculate_basic_risk_metrics(portfolio_returns), 'var_analysis': self._comprehensive_var_analysis(portfolio_returns), 'stress_testing': self._perform_stress_testing(portfolio_returns), 'risk_decomposition': None}
        if len(asset_names) > 1:
            results['risk_decomposition'] = VaRCalculations.component_var(portfolio_returns, returns_matrix, weights)
        results['dollar_metrics'] = self._convert_to_dollar_metrics(results, portfolio_value)
        return results

    def _calculate_basic_risk_metrics(self, returns: np.ndarray) -> Dict:
        """Calculate basic risk metrics"""
        return {'volatility_daily': np.std(returns, ddof=1), 'volatility_annual': np.std(returns, ddof=1) * np.sqrt(MathConstants.TRADING_DAYS_YEAR), 'downside_deviation': StatisticalCalculations.calculate_downside_deviation(returns), 'max_drawdown': self._calculate_max_drawdown(returns), 'skewness': stats.skew(returns), 'kurtosis': stats.kurtosis(returns, fisher=False), 'jarque_bera_test': stats.jarque_bera(returns)}

    def _comprehensive_var_analysis(self, returns: np.ndarray) -> Dict:
        """Comprehensive VaR analysis with multiple methods"""
        var_results = {}
        for confidence_level in self.parameters.var_confidence_levels:
            var_results[f'var_{int(confidence_level * 100)}'] = {'parametric_normal': VaRCalculations.parametric_var(returns, confidence_level, distribution='normal'), 'parametric_t': VaRCalculations.parametric_var(returns, confidence_level, distribution='t_distribution'), 'historical': {'var': RiskCalculations.value_at_risk_historical(returns, confidence_level), 'cvar': RiskCalculations.conditional_value_at_risk(returns, confidence_level)}, 'monte_carlo': VaRCalculations.monte_carlo_var(returns, confidence_level, num_simulations=self.parameters.monte_carlo_simulations)}
        return var_results

    def _perform_stress_testing(self, returns: np.ndarray) -> Dict:
        """Perform comprehensive stress testing"""
        return ScenarioAnalysis.stress_testing(returns, self.parameters.stress_scenarios)

    def _calculate_max_drawdown(self, returns: np.ndarray) -> Dict:
        """Calculate maximum drawdown statistics"""
        cumulative_returns = np.cumprod(1 + returns)
        running_max = np.maximum.accumulate(cumulative_returns)
        drawdown = (cumulative_returns - running_max) / running_max
        max_dd = np.min(drawdown)
        max_dd_idx = np.argmin(drawdown)
        peak_idx = np.argmax(running_max[:max_dd_idx + 1]) if max_dd_idx > 0 else 0
        return {'max_drawdown': max_dd, 'peak_to_trough_days': max_dd_idx - peak_idx, 'drawdown_series': drawdown}

    def _convert_to_dollar_metrics(self, results: Dict, portfolio_value: float) -> Dict:
        """Convert percentage metrics to dollar amounts"""
        dollar_metrics = {}
        if 'var_analysis' in results:
            for var_level, var_data in results['var_analysis'].items():
                dollar_metrics[var_level] = {}
                if 'historical' in var_data:
                    dollar_metrics[var_level]['historical_var'] = var_data['historical']['var'] * portfolio_value
                    dollar_metrics[var_level]['historical_cvar'] = var_data['historical']['cvar'] * portfolio_value
                if 'parametric_normal' in var_data:
                    dollar_metrics[var_level]['parametric_var'] = var_data['parametric_normal']['var'] * portfolio_value
        return dollar_metrics

def _convert_to_dollar_metrics(self, results: Dict, portfolio_value: float) -> Dict:
    """Convert percentage metrics to dollar amounts"""
    dollar_metrics = {}
    if 'var_analysis' in results:
        for var_level, var_data in results['var_analysis'].items():
            dollar_metrics[var_level] = {}
            if 'historical' in var_data:
                dollar_metrics[var_level]['historical_var'] = var_data['historical']['var'] * portfolio_value
                dollar_metrics[var_level]['historical_cvar'] = var_data['historical']['cvar'] * portfolio_value
            if 'parametric_normal' in var_data:
                dollar_metrics[var_level]['parametric_var'] = var_data['parametric_normal']['var'] * portfolio_value
    return dollar_metrics

class IPSFramework:
    """Investment Policy Statement framework and construction"""

    @staticmethod
    def create_ips_template() -> Dict:
        """Create comprehensive IPS template"""
        return {'executive_summary': {'purpose': 'Define investment objectives, constraints, and guidelines', 'scope': 'Applies to all investment assets under management', 'governance': 'Oversight and decision-making framework'}, 'client_information': {'client_type': 'Individual/Institutional', 'contact_information': {}, 'background': 'Client history and context', 'financial_situation': 'Current financial position'}, 'investment_objectives': {'return_objectives': {'primary_objective': None, 'target_return': None, 'return_requirements': [], 'benchmark': None}, 'risk_objectives': {'risk_tolerance': None, 'risk_capacity': None, 'risk_constraints': [], 'maximum_acceptable_loss': None}}, 'investment_constraints': {'liquidity': {'liquidity_requirements': None, 'emergency_fund': None, 'cash_flow_needs': []}, 'time_horizon': {'investment_horizon': None, 'sub_periods': [], 'horizon_changes': []}, 'tax': {'tax_status': None, 'tax_concerns': [], 'tax_optimization': []}, 'legal_regulatory': {'applicable_regulations': [], 'compliance_requirements': [], 'prohibited_investments': []}, 'unique_circumstances': {'special_considerations': [], 'preferences': [], 'restrictions': []}}, 'investment_guidelines': {'asset_allocation': {}, 'security_selection': {}, 'portfolio_construction': {}, 'risk_management': {}}, 'performance_measurement': {'benchmarks': [], 'evaluation_criteria': [], 'reporting_frequency': None}, 'responsibilities': {'client_responsibilities': [], 'advisor_responsibilities': [], 'third_party_responsibilities': []}, 'review_and_monitoring': {'review_frequency': None, 'review_triggers': [], 'update_procedures': []}}

    @staticmethod
    def validate_ips(ips: InvestmentPolicyStatement) -> Dict:
        """Validate IPS completeness and consistency"""
        validation_results = {'is_valid': True, 'errors': [], 'warnings': [], 'completeness_score': 0}
        required_sections = ['investment_objectives', 'investment_constraints', 'strategic_asset_allocation', 'performance_measurement']
        for section in required_sections:
            if not hasattr(ips, section) or not getattr(ips, section):
                validation_results['errors'].append(f'Missing required section: {section}')
                validation_results['is_valid'] = False
        if hasattr(ips, 'investment_objectives') and hasattr(ips, 'investment_constraints'):
            consistency_check = IPSFramework._check_objective_constraint_consistency(ips.investment_objectives, ips.investment_constraints)
            validation_results['warnings'].extend(consistency_check)
        validation_results['completeness_score'] = IPSFramework._calculate_completeness_score(ips)
        return validation_results

    @staticmethod
    def _check_objective_constraint_consistency(objectives: Dict, constraints: Dict) -> List[str]:
        """Check consistency between objectives and constraints"""
        warnings = []
        if objectives.get('return_objectives', {}).get('target_return', 0) > 0.1:
            if constraints.get('time_horizon', {}).get('investment_horizon', 10) < 5:
                warnings.append('High return target inconsistent with short time horizon')
        if constraints.get('liquidity', {}).get('liquidity_requirements', 0) > 0.3:
            if objectives.get('return_objectives', {}).get('target_return', 0) > 0.08:
                warnings.append('High liquidity needs may conflict with return objectives')
        return warnings

    @staticmethod
    def _calculate_completeness_score(ips: InvestmentPolicyStatement) -> float:
        """Calculate IPS completeness score"""
        sections = ['client_information', 'investment_objectives', 'investment_constraints', 'investment_guidelines', 'strategic_asset_allocation', 'rebalancing_policy', 'performance_measurement', 'responsibilities', 'review_schedule']
        completed_sections = sum((1 for section in sections if hasattr(ips, section) and getattr(ips, section)))
        return completed_sections / len(sections) * 100

@staticmethod
def validate_ips(ips: InvestmentPolicyStatement) -> Dict:
    """Validate IPS completeness and consistency"""
    validation_results = {'is_valid': True, 'errors': [], 'warnings': [], 'completeness_score': 0}
