class OptimizationConfig:
    """Configuration class for optimization parameters"""

    def __init__(self):
        self.risk_free_rate = 0.02
        self.confidence_level = 0.95
        self.lookback_days = 252
        self.rebalance_frequency = 'monthly'
        self.weight_bounds = (0, 1)
        self.l2_gamma = 0.1
        self.tau = 0.05
        self.risk_aversion = 1.0
        self.expected_returns_method = 'mean_historical_return'
        self.risk_model_method = 'sample_cov'
        self.optimization_target = 'max_sharpe'
        self.hrp_linkage_method = 'single'
        self.bl_pi_method = 'market_cap'

    def to_dict(self) -> Dict:
        """Convert config to dictionary"""
        return {'risk_free_rate': self.risk_free_rate, 'confidence_level': self.confidence_level, 'lookback_days': self.lookback_days, 'rebalance_frequency': self.rebalance_frequency, 'weight_bounds': self.weight_bounds, 'l2_gamma': self.l2_gamma, 'tau': self.tau, 'risk_aversion': self.risk_aversion, 'expected_returns_method': self.expected_returns_method, 'risk_model_method': self.risk_model_method, 'optimization_target': self.optimization_target, 'hrp_linkage_method': self.hrp_linkage_method, 'bl_pi_method': self.bl_pi_method}

    @classmethod
    def from_dict(cls, config_dict: Dict):
        """Create config from dictionary"""
        config = cls()
        for key, value in config_dict.items():
            if hasattr(config, key):
                setattr(config, key, value)
        return config

    @monitor_performance
    def calculate_efficient_frontier(self, mu: pd.Series, S: pd.DataFrame, num_points: int=100, risk_range: Tuple[float, float]=None) -> Dict:
        """
        Calculate the efficient frontier

        Args:
            mu: Expected returns
            S: Covariance matrix
            num_points: Number of points on the frontier
            risk_range: Risk range (min_vol, max_vol)

        Returns:
            Dictionary with frontier data
        """
        try:
            with operation('calculate_efficient_frontier'):
                if risk_range is None:
                    ef_temp = EfficientFrontier(mu, S)
                    ef_temp.min_volatility()
                    min_vol = ef_temp.portfolio_performance()[1]
                    max_return = mu.max()
                    ef_temp = EfficientFrontier(mu, S)
                    try:
                        ef_temp.efficient_return(max_return * 0.95)
                        max_vol = ef_temp.portfolio_performance()[1]
                    except:
                        max_vol = min_vol * 3
                    risk_range = (min_vol, max_vol)
                min_return = mu.min()
                max_return = mu.max() * 0.95
                target_returns = np.linspace(min_return, max_return, num_points)
                frontier_returns = []
                frontier_volatilities = []
                frontier_weights = []
                for target_return in target_returns:
                    try:
                        ef_temp = EfficientFrontier(mu, S)
                        ef_temp.efficient_risk(target_return)
                        ret, vol, _ = ef_temp.portfolio_performance()
                        if ret >= min_return and vol >= risk_range[0] and (vol <= risk_range[1] * 1.2):
                            frontier_returns.append(ret)
                            frontier_volatilities.append(vol)
                            frontier_weights.append(dict(ef_temp.weights))
                    except Exception as e:
                        logger.debug(f'Skipping target return {target_return:.4f}: {e}')
                        continue
                if not frontier_returns:
                    raise ValueError('Unable to generate efficient frontier points')
                ef_sharpe = EfficientFrontier(mu, S)
                ef_sharpe.max_sharpe(risk_free_rate=self.risk_free_rate)
                sharpe_performance = ef_sharpe.portfolio_performance(risk_free_rate=self.risk_free_rate)
                ef_min_vol = EfficientFrontier(mu, S)
                ef_min_vol.min_volatility()
                min_vol_performance = ef_min_vol.portfolio_performance(risk_free_rate=self.risk_free_rate)
                frontier_data = list(zip(frontier_volatilities, frontier_returns, frontier_weights))
                frontier_data.sort(key=lambda x: x[0])
                sorted_volatilities, sorted_returns, sorted_weights = zip(*frontier_data)
                return {'returns': list(sorted_returns), 'volatilities': list(sorted_volatilities), 'weights': list(sorted_weights), 'max_sharpe': {'return': sharpe_performance[0], 'volatility': sharpe_performance[1], 'sharpe_ratio': sharpe_performance[2], 'weights': dict(ef_sharpe.weights)}, 'min_volatility': {'return': min_vol_performance[0], 'volatility': min_vol_performance[1], 'sharpe_ratio': min_vol_performance[2], 'weights': dict(ef_min_vol.weights)}, 'risk_range': risk_range, 'num_points': len(sorted_returns)}
        except Exception as e:
            logger.error(f'Error calculating efficient frontier: {e}')
            raise

@classmethod
def from_dict(cls, config_dict: Dict):
    """Create config from dictionary"""
    config = cls()
    for key, value in config_dict.items():
        if hasattr(config, key):
            setattr(config, key, value)
    return config

